def main():
    questions = get_hard_questions()
    print(f"Generated {len(questions)} Hard questions.")
    assert len(questions) == 50, f"Expected 50 questions, got {len(questions)}"

    # Check and ensure sequential IDs
    for idx, q in enumerate(questions, 1):
        q["id"] = f"UT_H_{idx:03d}"

    balanced = balance_question_keys(questions)
    out_dir = os.path.join("data", "questions", "polity")
    os.makedirs(out_dir, exist_ok=True)
    out_file = os.path.join(out_dir, "union_territory_hard.json")

    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(balanced, f, ensure_ascii=False, indent=2)
    print(f"Saved {len(balanced)} questions to {out_file}")

    res = ContentValidator.validate_file(out_file, expected_count=50, expected_prefix="UT_H_")
    print("\n--- ContentValidator Summary ---")
    print(res.summary())
    if not res.is_valid:
        print("Issues:", res.issues)
    else:
        print("\nALL 50 HARD QUESTIONS VALIDATED PERFECTLY! (PASS)")

if __name__ == "__main__":
    main()
